"""Generate tests/fixtures/corpus-l5: a synthetic 48-hour corpus whose realised schedule gives every L5 template
something to bind.

  uv run python tests/fixtures/make_corpus_l5.py tests/fixtures/corpus-l5

`build` takes another scenario and a deploy driver, for tests that need a corpus with releases (a bad deploy, a
benign_deploy) driven by it: while a release is out its service's spans carry the release's service.version.

No live capture has had overlapping or sequential faults, a cascade, a release or a quiet day, so this corpus
supplies them. The schedule is not hand-written: SCENARIO below is planned by `otb.scenario.plan` and executed by
`otb.inject.Injector` against an in-memory copy of the pinned flagd config and a decoy driver that always succeeds,
on a simulated clock, so events.jsonl and schedule.yaml come from the injector's own code. The telemetry is then
simulated from the realised schedule: a checkout and a browse request every minute through a small OTel Demo
topology, and each fault flag, while on, doing what it does in the demo. Same script, same bytes: the segments,
and so the corpus id, are a pure function of this file (the manifest's created_utc is the only clock read).

Timeline (hours from the capture start, 2026-10-05T00:00Z):
  23:00  q1  quiet window, 10 min: the control for the needle (a quiet day around it) and for the overlap pair
  26:00  n1  paymentFailure 50%, 12 min: the needle, alone in its 24 hours
  30:00  f2a paymentFailure 50% and, from 30:08, f2b cartFailure 50%: two overlapping faults on different services
  36:00  c1  productCatalogFailure: a cascade whose loudest symptom is checkout, which retries the failing call
  38:40  d1  benign_deploy of recommendation (a new service.version), 20 min before
  39:00  r1  paymentFailure 75%: the fault the release did not cause
  42:00  s1  adFailure, 10 min, then from 42:20 s2 intlShippingSlowdown 10 s: two sequential incidents
  45:30  d2  benign_deploy of cart, 30 min before
  46:00  a1  adFailure, 10 min: a fault beside a release that fails no checkout, which l5-red-herring must not bind
"""

from __future__ import annotations

import copy
import random
import sys
import time
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from unittest import mock

import orjson

from otb.archive import ArchiveWriter, Header, Manifest, NormaliserStamp, SourcePins
from otb.inject import DeployDriver, Injector
from otb.normalise import normalise
from otb.scenario import Catalogue, PlannedEntry, RealisedEntry, load_scenario, plan, sha256_bytes

NS = 1_000_000_000
MS = 1_000_000
CAPTURE_START_NS = 1_791_158_400 * NS
SEED = 5
MINUTE_NS = 60 * NS
FRAME_NS = 600 * NS
CALLS = "traces.span.metrics.calls"
FLAGD = Path(__file__).resolve().parent / "flagd" / "demo.flagd.json"

SCENARIO = """\
id: corpus-l5
seed: 5
duration_s: 172800
instances: [default]
min_gap_s: 0
note: synthetic; generated by tests/fixtures/make_corpus_l5.py
slots:
  - { id: q1, kind: quiet, start_s: { lo: 82800, hi: 82800 }, duration_s: { lo: 600, hi: 600 } }
  - id: n1
    kind: fault
    flag_in: [paymentFailure]
    variant_in: ["50%"]
    start_s: { lo: 93600, hi: 93600 }
    duration_s: { lo: 720, hi: 720 }
    instance: default
  - id: f2a
    kind: fault
    flag_in: [paymentFailure]
    variant_in: ["50%"]
    start_s: { lo: 108000, hi: 108000 }
    duration_s: { lo: 1200, hi: 1200 }
    instance: default
    group: g2
    relation: overlap
  - id: f2b
    kind: fault
    flag_in: [cartFailure]
    variant_in: ["50%"]
    start_s: { lo: 480, hi: 480 }
    duration_s: { lo: 1200, hi: 1200 }
    instance: default
    group: g2
    relation: overlap
  - id: c1
    kind: fault
    flag_in: [productCatalogFailure]
    start_s: { lo: 129600, hi: 129600 }
    duration_s: { lo: 900, hi: 900 }
    instance: default
    group: gc
    relation: cascade
  - id: d1
    kind: decoy
    type: benign_deploy
    target_in: [recommendation]
    start_s: { lo: 139200, hi: 139200 }
    duration_s: { lo: 120, hi: 120 }
    instance: default
    params: { version_to: 2.0.1 }
  - id: r1
    kind: fault
    flag_in: [paymentFailure]
    variant_in: ["75%"]
    start_s: { lo: 140400, hi: 140400 }
    duration_s: { lo: 900, hi: 900 }
    instance: default
  - id: s1
    kind: fault
    flag_in: [adFailure]
    start_s: { lo: 151200, hi: 151200 }
    duration_s: { lo: 600, hi: 600 }
    instance: default
    group: gs
    relation: back_to_back
  - id: s2
    kind: fault
    flag_in: [intlShippingSlowdown]
    variant_in: ["10sec"]
    start_s: { lo: 600, hi: 600 }
    duration_s: { lo: 600, hi: 600 }
    instance: default
    group: gs
    relation: back_to_back
  - id: d2
    kind: decoy
    type: benign_deploy
    target_in: [cart]
    start_s: { lo: 163800, hi: 163800 }
    duration_s: { lo: 120, hi: 120 }
    instance: default
    params: { version_to: 2.0.1 }
  - id: a1
    kind: fault
    flag_in: [adFailure]
    start_s: { lo: 165600, hi: 165600 }
    duration_s: { lo: 600, hi: 600 }
    instance: default
"""

PAY = "Payment request failed. Invalid token. app.loyalty.level=gold"
CART = "Can't access cart storage. System.ApplicationException: Wasn't able to connect to redis"
PRODUCT = "Error: Product Catalog Fail Feature Flag Enabled"
AD = "GetAds failed: ad lookup aborted by the request filter"
# Share of requests a flag at variant "on" fails: productCatalogFailure fails one product id, in about half the
# carts; adFailure fails a share of ad lookups.
ON_RATE = {"adFailure": 0.5, "productCatalogFailure": 0.5}
SERVER, CLIENT = 2, 3


class SimulatedFlagd:
    def __init__(self) -> None:
        self.config = orjson.loads(FLAGD.read_bytes())

    def read(self) -> dict:
        return copy.deepcopy(self.config)

    def write(self, config: dict) -> tuple[bool, dict[str, str]]:
        self.config = copy.deepcopy(config)
        return True, {"via": "simulated flagd"}

    def served_variant(self, flag: str) -> str | None:
        return None


class SimulatedDecoys:
    def preflight(self, entry: PlannedEntry, instance: str) -> list[str]:
        return []

    def start(self, entry: PlannedEntry, instance: str) -> tuple[bool, dict[str, str]]:
        return True, {"via": "simulated", "target": entry.target or ""}

    def stop(self, entry: PlannedEntry, instance: str) -> tuple[bool, dict[str, str]]:
        return True, {"via": "simulated"}

    def set_users(self, instance: str, users: int) -> tuple[bool, dict[str, str]]:
        return True, {"via": "simulated", "users": str(users)}


def run_injector(
    out: Path, scenario_text: str = SCENARIO, deploys: DeployDriver | None = None
) -> tuple[bytes, bytes, list[RealisedEntry]]:
    """The scenario planned and injected on a simulated clock: every action takes 20 ms, waits take no time."""
    (out / "scenario.yaml").write_text(scenario_text)
    scenario = load_scenario(out / "scenario.yaml")
    cat = Catalogue.load()
    p = plan(scenario, cat, SEED)
    now = [CAPTURE_START_NS]

    def clock() -> int:
        now[0] += 20 * MS
        return now[0]

    def sleep(s: float) -> None:
        now[0] += round(s * NS)

    events = out / "events.jsonl"
    events.unlink(missing_ok=True)
    inj = Injector(
        p,
        cat,
        {"default": SimulatedFlagd()},
        events,
        CAPTURE_START_NS,
        decoys=SimulatedDecoys(),
        deploys=deploys,
        clock=clock,
        sleep=sleep,
    )
    if problems := inj.preflight():
        raise SystemExit("\n".join(problems))
    with mock.patch.object(time, "monotonic", lambda: 0.0):
        schedule = inj.run()
    return p.to_yaml(), schedule.to_yaml(), [e for e in schedule.entries if e.status == "realised"]


@dataclass
class Call:
    """One span to lay out: its own time, its error, the log records it writes and the calls below it."""

    service: str
    name: str
    kind: int
    self_ms: float
    error: str | None = None
    attrs: dict = field(default_factory=dict)
    logs: list[tuple[int, str, str]] = field(default_factory=list)
    children: list[Call] = field(default_factory=list)


def rpc(caller: str, name: str, callee: Call, error: str | None = None) -> Call:
    return Call(caller, name, CLIENT, 0.3, error, children=[callee])


def kv(key: str, value: object) -> dict:
    if isinstance(value, int):
        return {"key": key, "value": {"intValue": str(value)}}
    return {"key": key, "value": {"stringValue": str(value)}}


def release(f: RealisedEntry) -> tuple[str, str, int, int]:
    """(service, version, from, to) of a release the deploy driver made: from the change it applied to the rollback
    it applied."""
    applied = [a for a in f.actions if a.action == "deploy.apply" and a.ok]
    to = next(a.detail["to_version"] for a in f.actions if a.action == "deploy.confirm" and a.detail["phase"] == "on")
    rolled_back = next((a.at_ns for a in applied if a.detail["phase"] == "off"), f.window.end)
    return f.target or "", to, applied[0].at_ns, rolled_back


class Telemetry:
    """Spans, log records and the span-derived calls metric (one cumulative point per series per minute, as the
    collector's spanmetrics connector writes it), bucketed by 10 minutes and resource: one export request per signal
    per bucket."""

    def __init__(self, entries: list[RealisedEntry], rng: random.Random) -> None:
        self.rng = rng
        self.faults = [e for e in entries if e.kind == "fault"]
        released = [e for e in entries if any(a.action == "deploy.confirm" for a in e.actions)]
        self.deploys = [e for e in entries if e.decoy_type == "benign_deploy" and e not in released]
        self.releases = [release(e) for e in released]
        self.spans: dict[int, dict[tuple[str, str, str], list[dict]]] = defaultdict(lambda: defaultdict(list))
        self.logs: dict[int, dict[tuple[str, str, str], list[dict]]] = defaultdict(lambda: defaultdict(list))
        self.calls: dict[tuple, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def variant(self, flag: str, t: int) -> str | None:
        return next((f.variant for f in self.faults if f.flag == flag and f.window.start <= t < f.window.end), None)

    def fails(self, flag: str, t: int) -> bool:
        v = self.variant(flag, t)
        if v is None:
            return False
        rate = float(v.rstrip("%")) / 100 if v.endswith("%") else ON_RATE[flag]
        return self.rng.random() < rate

    def resource(self, service: str, t: int) -> tuple[str, str, str]:
        for target, version, released, rolled_back in self.releases:
            if target == service and released <= t < rolled_back:
                return service, version, f"{service}-{version}"
        deployed = [d for d in self.deploys if d.target == service and d.window.start <= t]
        if deployed:
            return service, "2.0.1", f"{service}-2"
        return service, "2.0.0", f"{service}-1"

    def ms(self, base: float) -> float:
        return base * self.rng.uniform(0.8, 1.25)

    def emit(self, c: Call, start: int, trace: str, parent: str | None) -> int:
        sid = f"{self.rng.getrandbits(64):016x}"
        t = start + round(0.2 * MS)
        for child in c.children:
            t = self.emit(child, t, trace, sid) + round(0.2 * MS)
        end = t + round(self.ms(c.self_ms) * MS)
        span = {
            "traceId": trace,
            "spanId": sid,
            "name": c.name,
            "kind": c.kind,
            "startTimeUnixNano": str(start),
            "endTimeUnixNano": str(end),
            "attributes": [kv(k, v) for k, v in c.attrs.items()],
        }
        if parent:
            span["parentSpanId"] = parent
        if c.error is not None:
            span["status"] = {"code": 2, "message": c.error}
        res = self.resource(c.service, start)
        self.spans[start // FRAME_NS][res].append(span)
        kind = "SPAN_KIND_SERVER" if c.kind == SERVER else "SPAN_KIND_CLIENT"
        status = "STATUS_CODE_UNSET" if c.error is None else "STATUS_CODE_ERROR"
        self.calls[(res, c.name, kind, status)][start // MINUTE_NS] += 1
        for i, (sev, text, body) in enumerate(c.logs):
            ts = start + (i + 1) * MS
            record = {
                "timeUnixNano": str(ts),
                "severityNumber": sev,
                "severityText": text,
                "body": {"stringValue": body},
            }
            self.logs[ts // FRAME_NS][res].append(record | {"traceId": trace, "spanId": sid})
        return end

    def checkout(self, t: int) -> None:
        cart_fails = self.fails("cartFailure", t)
        product_fails = not cart_fails and self.fails("productCatalogFailure", t)
        pay_fails = not cart_fails and not product_fails and self.fails("paymentFailure", t)
        cart = Call("cart", "POST /oteldemo.CartService/GetCart", SERVER, 2)
        calls = [rpc("checkout", "oteldemo.CartService/GetCart", cart)]
        failed = None
        if cart_fails:
            cart.error, cart.logs = CART, [(17, "ERROR", CART)]
            calls[0].error = "rpc error: code = FailedPrecondition desc = " + CART
            failed = "failed to get user cart during checkout: " + calls[0].error
        else:
            for _ in range(2 if product_fails else 1):
                product = Call("product-catalog", "oteldemo.ProductCatalogService/GetProduct", SERVER, 1)
                call = rpc("checkout", "oteldemo.ProductCatalogService/GetProduct", product)
                if product_fails:
                    product.error, product.logs = PRODUCT, [(17, "ERROR", PRODUCT)]
                    call.error = "rpc error: code = Internal desc = " + PRODUCT
                calls.append(call)
            if product_fails:
                failed = 'failed to prepare order: failed to get product #"OLJCESPC7Z": ' + calls[-1].error
        if failed is None:
            slow = self.variant("intlShippingSlowdown", t)
            quote = Call("shipping", "oteldemo.ShippingService/GetQuote", SERVER, 10_000 if slow else 3)
            charge = Call("payment", "charge", SERVER, 4)
            calls += [rpc("checkout", "oteldemo.ShippingService/GetQuote", quote)]
            calls += [rpc("checkout", "oteldemo.PaymentService/Charge", charge)]
            if pay_fails:
                charge.error, charge.logs = PAY, [(13, "WARN", PAY)]
                calls[-1].error = "rpc error: code = Unknown desc = " + PAY
                failed = "failed to charge card: could not charge the card: " + calls[-1].error
            else:
                charge.logs = [(9, "INFO", "Transaction complete.")]
        status = 500 if failed else 200
        place = Call("checkout", "oteldemo.CheckoutService/PlaceOrder", SERVER, 2, failed, children=calls)
        if failed:
            place.logs = [(17, "ERROR", failed)]
        front = Call(
            "frontend",
            "POST /api/checkout",
            SERVER,
            5,
            "Checkout failed to place order" if failed else None,
            {"http.response.status_code": status},
            children=[place],
        )
        proxy = Call(
            "frontend-proxy",
            "POST",
            SERVER,
            1,
            "" if failed else None,
            {"url.path": "/api/checkout", "http.response.status_code": status},
            children=[front],
        )
        self.emit(proxy, t, f"{self.rng.getrandbits(128):032x}", None)

    def browse(self, t: int) -> None:
        ad = Call("ad", "oteldemo.AdService/GetAds", SERVER, 3)
        get_ads = rpc("frontend", "oteldemo.AdService/GetAds", ad)
        if self.fails("adFailure", t):
            ad.error, ad.logs = AD, [(17, "ERROR", AD)]
            get_ads.error = "13 INTERNAL: " + AD
        rec = Call("recommendation", "oteldemo.RecommendationService/ListRecommendations", SERVER, 6)
        recs = rpc("frontend", "oteldemo.RecommendationService/ListRecommendations", rec)
        front = Call("frontend", "GET /api/data", SERVER, 4, None, {"http.response.status_code": 200})
        front.children = [get_ads, recs]
        proxy = Call(
            "frontend-proxy",
            "GET",
            SERVER,
            1,
            None,
            {"url.path": "/api/data", "http.response.status_code": 200},
            children=[front],
        )
        self.emit(proxy, t, f"{self.rng.getrandbits(128):032x}", None)

    def frames(self) -> list[tuple[str, bytes]]:
        def resources(by_res: dict, inner: str, records: str) -> list[dict]:
            return [
                {
                    "resource": {
                        "attributes": [kv("service.name", s), kv("service.version", v), kv("service.instance.id", i)]
                    },
                    inner: [{"scope": {"name": "otb.synthetic"}, records: recs}],
                }
                for (s, v, i), recs in sorted(by_res.items())
            ]

        points: dict[int, dict[tuple[str, str, str], list[dict]]] = defaultdict(lambda: defaultdict(list))
        last = max(m for per_minute in self.calls.values() for m in per_minute)
        for (res, name, kind, status), per_minute in sorted(self.calls.items()):
            first, total = min(per_minute), 0
            attrs = {"service.name": res[0], "span.name": name, "span.kind": kind, "status.code": status}
            for m in range(first, last + 1):
                total += per_minute.get(m, 0)
                t = (m + 1) * MINUTE_NS
                point = {
                    "startTimeUnixNano": str(first * MINUTE_NS),
                    "timeUnixNano": str(t),
                    "asInt": str(total),
                    "attributes": [kv(k, v) for k, v in attrs.items()],
                }
                points[t // FRAME_NS][res].append(point)

        def metrics(by_res: dict) -> list[dict]:
            out = []
            for (s, v, i), pts in sorted(by_res.items()):
                sum_ = {"dataPoints": pts, "aggregationTemporality": 2, "isMonotonic": True}
                out.append(
                    {
                        "resource": {
                            "attributes": [
                                kv("service.name", s),
                                kv("service.version", v),
                                kv("service.instance.id", i),
                            ]
                        },
                        "scopeMetrics": [{"scope": {"name": "spanmetrics"}, "metrics": [{"name": CALLS, "sum": sum_}]}],
                    }
                )
            return out

        out = []
        for bucket in sorted(self.spans.keys() | self.logs.keys() | points.keys()):
            if bucket in self.spans:
                doc = {"resourceSpans": resources(self.spans[bucket], "scopeSpans", "spans")}
                out.append(("traces", orjson.dumps(doc)))
            if bucket in self.logs:
                doc = {"resourceLogs": resources(self.logs[bucket], "scopeLogs", "logRecords")}
                out.append(("logs", orjson.dumps(doc)))
            if bucket in points:
                out.append(("metrics", orjson.dumps({"resourceMetrics": metrics(points[bucket])})))
        return out


def build(out: Path, scenario_text: str = SCENARIO, deploys: DeployDriver | None = None) -> Manifest:
    out.mkdir(parents=True, exist_ok=True)
    for stale in ("manifest.yaml", "segments.jsonl", ".writer.lock"):
        (out / stale).unlink(missing_ok=True)
    for seg in sorted(out.glob("segments/*/*/*"), reverse=True):
        seg.unlink()
    plan_yaml, schedule_yaml, entries = run_injector(out, scenario_text, deploys)
    (out / "plan.yaml").write_bytes(plan_yaml)
    (out / "schedule.yaml").write_bytes(schedule_yaml)
    rng = random.Random(SEED)
    tel = Telemetry(entries, rng)
    duration_s = load_scenario(out / "scenario.yaml").duration_s
    for minute in range(duration_s // 60):
        t0 = CAPTURE_START_NS + minute * 60 * NS
        tel.checkout(t0 + round(rng.uniform(5, 25) * NS))
        tel.browse(t0 + round(rng.uniform(35, 55) * NS))
    header = Header(
        out.name,
        ("default",),
        SourcePins("synthetic: tests/fixtures/make_corpus_l5.py", "none", "none", {}, "none"),
        NormaliserStamp.current(),
        rotate_bytes=1 << 20,
    )
    w = ArchiveWriter(out, header, rotate_s=None, dedupe=False)
    for signal, body in tel.frames():
        w.append(signal, normalise(signal, body), received_ns=0)
    m = w.seal(scenario_sha256=sha256_bytes(scenario_text.encode()), schedule_sha256=sha256_bytes(schedule_yaml))
    w.close()
    return m


def main() -> int:
    out = Path(sys.argv[1])
    print(f"{out}: corpus_id {build(out).corpus_id}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
